CREATE TABLE system_setting (setting_key TEXT PRIMARY KEY, setting_value TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE app_user (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, active INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE role (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE);
CREATE TABLE user_role (user_id TEXT NOT NULL REFERENCES app_user(id), role_id TEXT NOT NULL REFERENCES role(id), PRIMARY KEY (user_id, role_id));
CREATE TABLE route (id TEXT PRIMARY KEY, name TEXT NOT NULL, collector_id TEXT REFERENCES app_user(id), active INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE customer (id TEXT PRIMARY KEY, full_name TEXT NOT NULL, document_number TEXT NOT NULL UNIQUE, phone TEXT NOT NULL, alt_phone TEXT, address TEXT, neighborhood TEXT, city TEXT, occupation TEXT, business_name TEXT, notes TEXT, status TEXT NOT NULL, route_id TEXT REFERENCES route(id), collector_id TEXT REFERENCES app_user(id), created_at TEXT NOT NULL);
CREATE TABLE customer_reference (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer(id), full_name TEXT NOT NULL, relationship TEXT NOT NULL, phone TEXT NOT NULL, address TEXT);
CREATE TABLE loan (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer(id), route_id TEXT REFERENCES route(id), collector_id TEXT REFERENCES app_user(id), previous_loan_id TEXT REFERENCES loan(id), operation_type TEXT NOT NULL, principal NUMERIC NOT NULL, interest_rate NUMERIC NOT NULL, interest_amount NUMERIC NOT NULL, total_agreed NUMERIC NOT NULL, installment_count INTEGER NOT NULL, frequency TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE installment (id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loan(id), installment_number INTEGER NOT NULL, due_date TEXT NOT NULL, amount NUMERIC NOT NULL, paid_amount NUMERIC NOT NULL DEFAULT 0, status TEXT NOT NULL, UNIQUE (loan_id, installment_number));
CREATE TABLE collection_session (id TEXT PRIMARY KEY, route_id TEXT NOT NULL REFERENCES route(id), collector_id TEXT NOT NULL REFERENCES app_user(id), session_date TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT, status TEXT NOT NULL, expected_collection NUMERIC NOT NULL, actual_collection NUMERIC NOT NULL DEFAULT 0, notes TEXT);
CREATE TABLE payment (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, loan_id TEXT NOT NULL REFERENCES loan(id), customer_id TEXT NOT NULL REFERENCES customer(id), collector_id TEXT NOT NULL REFERENCES app_user(id), session_id TEXT REFERENCES collection_session(id), amount NUMERIC NOT NULL, method TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, annulment_reason TEXT);
CREATE TABLE payment_allocation (id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payment(id), installment_id TEXT NOT NULL REFERENCES installment(id), amount NUMERIC NOT NULL);
CREATE TABLE renewal (id TEXT PRIMARY KEY, previous_loan_id TEXT NOT NULL REFERENCES loan(id), new_loan_id TEXT NOT NULL REFERENCES loan(id), new_principal NUMERIC NOT NULL, previous_balance_deducted NUMERIC NOT NULL, paperwork_deducted NUMERIC NOT NULL, actual_cash_disbursed NUMERIC NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE payment_promise (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer(id), loan_id TEXT REFERENCES loan(id), amount NUMERIC NOT NULL, promised_date TEXT NOT NULL, status TEXT NOT NULL, notes TEXT, created_at TEXT NOT NULL);
CREATE TABLE delinquency_record (id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loan(id), installment_id TEXT REFERENCES installment(id), overdue_days INTEGER NOT NULL, overdue_amount NUMERIC NOT NULL, surcharge_amount NUMERIC NOT NULL DEFAULT 0, calculated_at TEXT NOT NULL);
CREATE TABLE cash_movement (id TEXT PRIMARY KEY, route_id TEXT REFERENCES route(id), collector_id TEXT REFERENCES app_user(id), session_id TEXT REFERENCES collection_session(id), movement_type TEXT NOT NULL, category TEXT NOT NULL, amount NUMERIC NOT NULL, reference_id TEXT, description TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE daily_settlement (id TEXT PRIMARY KEY, session_id TEXT NOT NULL UNIQUE REFERENCES collection_session(id), expected_collection NUMERIC NOT NULL, actual_collection NUMERIC NOT NULL, cash_difference NUMERIC NOT NULL, difference_justification TEXT, status TEXT NOT NULL, settled_at TEXT NOT NULL);
CREATE TABLE weekly_settlement (id TEXT PRIMARY KEY, route_id TEXT REFERENCES route(id), collector_id TEXT REFERENCES app_user(id), period_start TEXT NOT NULL, period_end TEXT NOT NULL, total_collections NUMERIC NOT NULL, new_loans_capital NUMERIC NOT NULL, renewals_capital NUMERIC NOT NULL, paperwork_total NUMERIC NOT NULL, disbursements_total NUMERIC NOT NULL, delinquency_recovered NUMERIC NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, user_id TEXT REFERENCES app_user(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, previous_value TEXT, new_value TEXT, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE sync_operation (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, operation_type TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, last_error TEXT);
